/* aesthetic scroll v2.22.1 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-measure: 38rem;
  --ae-space-5: 1.5em;
  --ae-space-6: 2em;
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

.ae-stage {
flex: 1;
  min-height: 0;
  width: min(var(--ae-measure), 100% - 5rem);
  margin-inline: auto;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}

.ae-stage > * {
margin-block: auto;
  padding-block: var(--ae-space-5);
}

.ae-stage-scroll > * {
margin-block: 0;
  padding-block: var(--ae-space-6);
}

@media (max-width: 40rem) {
  .ae-stage {
  width: calc(100% - 2.4rem);
  }
}
